cat << 'EOF' > /app/generate_batch.py
import os
import json
import base64
import mimetypes

files = os.listdir('/app/documents/')
files.sort()

schema = {
    "type": "object",
    "properties": {
        "type": {
            "type": "string",
            "enum": ["invoice", "other"],
            "description": "Classify the document as 'invoice' or 'other'"
        },
        "total_amount": {
            "type": "number",
            "description": "Total amount including tax (look for terms like 'Total', 'Amount Due', 'Grand Total'). If both 'Total' and 'Amount Due' are present with different values, use only 'Total'."
        },
        "vat_amount": {
            "type": "number",
            "description": "VAT amount (look for terms like 'VAT', 'Tax', 'GST'). If VAT is not present, set it to 0."
        }
    },
    "required": ["type", "total_amount", "vat_amount"]
}

def create_batch(files_batch, batch_index):
    inputs = []
    for f in files_batch:
        file_path = os.path.join('/app/documents/', f)
        mime_type, _ = mimetypes.guess_type(file_path)
        with open(file_path, "rb") as fp:
            encoded_string = base64.b64encode(fp.read()).decode('utf-8')

        url = f"data:{mime_type};base64,{encoded_string}"
        content = [
            {"type": "text", "text": "Analyze this document. Classify as 'invoice' or 'other'. If it's an invoice, extract the total amount and VAT amount. Output strictly in the given JSON schema."},
            {"type": "image_url", "image_url": {"url": url}}
        ]

        inputs.append({
            "id": f,
            "system_instructions": "You are a precise data extraction assistant.",
            "messages": [
                {
                    "role": "user",
                    "content": content
                }
            ],
            "response_json_schema": schema
        })

    with open(f"/app/batch_{batch_index}.json", "w") as fp:
        json.dump({"inputs": inputs}, fp)

create_batch(files[:9], 1)
create_batch(files[9:], 2)
EOF
python3 /app/generate_batch.py
ls -l /app/batch_*.json
